import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 88 · Christmas recipe: soft molasses cookies

sc("""Sweetheart, there's one Christmas cookie that every grandmother in America used to make, and almost nobody makes anymore. Soft, chewy molasses cookies, dark and spicy, with crackly sugar tops. They make the whole house smell like Christmas. But when people try them today, they come out flat and greasy, or hard as hockey pucks by the next morning. And it's always the same few mistakes.""",
   "soft molasses cookies crackly sugar tops", "FORGOTTEN COOKIE")
sc("""So tonight I'm giving you Grandma Pearl's soft molasses cookies, step by step, and the five mistakes that ruin them. And stay with me, because the last secret is something she put in the cookie tin, and it keeps them soft for two whole weeks. People think I bake them fresh every day.""",
   "vintage cookie tin Christmas", "SOFT FOR TWO WEEKS")

ch("Grandma Pearl's tin")
sc("""Grandma Pearl kept her molasses cookies in a big round tin with a picture of a sleigh on the lid. It sat on top of her icebox from Thanksgiving to New Year's, and it was never empty. Danny and I would climb on a chair to reach it. She always knew, honey. She'd say, two, not three, from the other room, without even turning around.""",
   "vintage sleigh cookie tin on icebox", "TWO, NOT THREE")
sc("""Molasses was the sweetener of poor families for two hundred years in America. White sugar was expensive, and molasses was cheap, so it went in everything. Baked beans, brown bread, gingerbread, and these cookies. In a minute I'll tell you which kind of molasses to buy, because one kind will ruin your cookies, and it's sitting right next to the good one on the shelf.""",
   "jar of dark molasses pouring", "THE POOR FAMILY'S SUGAR")
sc("""Grandma Pearl made these every December for the men who came to her farm to help butcher the hog, and for the mailman, and for the minister. She packed a dozen in waxed paper for every one of them. She said, a molasses cookie in your coat pocket will keep you warm all the way home. She wasn't wrong, honey. They're full of ginger.""",
   "cookies wrapped in wax paper bundle", "IN YOUR COAT POCKET")

sc("""And the first time I made them by myself, honey, I was twelve, and I used a tablespoon of ground cloves instead of a half teaspoon, because I misread Grandma Pearl's handwriting. My father took one bite and said, Ruthie, my whole mouth is numb. Danny said they tasted like the dentist's office. Grandma Pearl laughed until she cried, and then she rewrote the recipe card in big block letters.""",
   "handwritten recipe card block letters", "LIKE THE DENTIST")
ch("What you need")
sc("""Here's what you need for about three dozen. Three quarters of a cup of butter, soft. One cup of brown sugar, packed. One egg. One quarter cup of molasses. Two and a quarter cups of flour. Two teaspoons of baking soda. A quarter teaspoon of salt. Two teaspoons of ginger, one of cinnamon, half a teaspoon of cloves. And a little bowl of white sugar for rolling.""",
   "molasses cookie ingredients spices", "THE INGREDIENTS")
sc("""And here's mistake number one. Using blackstrap molasses. Blackstrap is the last boiling of the sugar cane, and it's bitter and harsh, almost like medicine. It makes your cookies taste burnt. You want the one that says original or mild. It's sweet and warm and tastes like caramel. Grandma Pearl called blackstrap the cough syrup, and wouldn't let it in her kitchen.""",
   "two molasses jars blackstrap and mild", "NOT BLACKSTRAP")
sc("""And mistake number two. Using old spices. Ground ginger and cinnamon lose their flavor after about a year in the cupboard. If yours has been sitting there since you moved in, buy a fresh jar. Open it and smell it. If it doesn't make you sneeze a little, it won't make your cookies taste like anything. A fresh jar costs about two dollars.""",
   "spice jars in cupboard", "FRESH SPICES")

ch("The dough")
sc("""Beat the soft butter and brown sugar together until they're light and fluffy, about two minutes. Beat in the egg and the molasses. In another bowl, whisk the flour, baking soda, salt, and spices. Then stir the dry into the wet, just until there's no flour showing. The dough will be soft and sticky, honey, the color of coffee with cream. That's right.""",
   "dark cookie dough in mixing bowl", "SOFT AND STICKY")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. And here's mistake number three. Baking the dough right away. It's too soft, and the cookies spread into thin, greasy puddles. Cover the bowl and chill it for at least one hour, or overnight. Cold dough holds its shape and bakes up thick and chewy.""",
   "covered bowl of dough in refrigerator", "CHILL THE DOUGH")
sc("""Grandma Pearl made her dough the night before and left it on the cold back porch. In the morning, it was firm as clay. And the spices had all night to blend into the molasses, so they tasted richer. If you make the dough on a Friday and bake on a Saturday, you'll have better cookies than if you did it all at once.""",
   "bowl of dough on cold back porch", "MAKE IT THE NIGHT BEFORE")

sc("""And measure your flour the right way, sweetheart, because too much flour is the other way to get hard cookies. Don't scoop the cup into the flour bag. That packs it down and you get a quarter cup extra without knowing it. Spoon the flour into the cup, then level it off with the back of a knife. It's the single most common baking mistake in America, and it's so easy to fix.""",
   "spooning flour into measuring cup leveling", "SPOON, DON'T SCOOP")
ch("Rolling and baking")
sc("""Heat your oven to three hundred fifty. Scoop the dough into balls about the size of a walnut. Roll each one in white sugar until it's completely covered. Put them on a baking sheet lined with parchment, two inches apart. They'll spread a little. And as they bake, the sugar on top cracks into those beautiful little crinkles that make them look like Christmas.""",
   "rolling dough balls in sugar", "ROLL IN SUGAR")
sc("""Bake for nine to ten minutes. And here's mistake number four, the most important one. Baking them until they look done. When you take them out, the edges should be set, but the centers should look puffy and a little underbaked, even raw. Take them out anyway. They keep baking on the hot pan, and they settle into soft, chewy middles. One extra minute, and you've got hockey pucks.""",
   "puffy underbaked cookies on baking sheet", "TAKE THEM OUT EARLY")
sc("""Let them sit on the hot pan for five minutes before you move them, honey. They're too soft to lift at first, and they'll break. Then move them to a rack to cool completely. And if you want a little extra Christmas, press a few pieces of crystallized ginger into the tops before baking. My granddaughter likes them dipped halfway in white chocolate.""",
   "cookies cooling on wire rack", "FIVE MINUTES ON THE PAN")

ch("The secret")
sc("""Now mistake number five, and the secret I promised you. Storing them wrong. Molasses cookies dry out fast in a cookie jar or on a plate. Grandma Pearl kept them in a tin with a tight lid. And in that tin, she always put one slice of plain white bread. Just one slice, tucked in at the side. And they stayed soft for two weeks.""",
   "slice of bread in cookie tin", "A SLICE OF BREAD")
sc("""The cookies pull the moisture out of the bread. A couple of days later, the bread is hard as a cracker, and the cookies are as soft as the day you made them. When the bread gets hard, put in a fresh slice. It works for any soft cookie, sweetheart. Sugar cookies, oatmeal cookies, snickerdoodles. It's the oldest trick in any grandmother's kitchen.""",
   "hard bread slice and soft cookies", "THE OLDEST TRICK")
sc("""And they freeze beautifully. Freeze the dough balls, already rolled in sugar, on a tray, and then put them in a bag. Bake them straight from the freezer, adding a minute. I keep a bag in my freezer all December. When company drops by, I bake six, and the house smells like Grandma Pearl's kitchen in eleven minutes.""",
   "frozen dough balls in bag", "STRAIGHT FROM THE FREEZER")

sc("""And if they do go hard, don't throw them out, honey. Crush them into crumbs with a rolling pin and use them as a crust for a pumpkin pie or a cheesecake, mixed with a little melted butter. Or crumble them over vanilla ice cream. Grandma Pearl never threw away one crumb. She said a stale cookie is just a pie crust that doesn't know it yet.""",
   "crushed cookie crumbs pie crust", "A PIE CRUST IN DISGUISE")
ch("Giving them")
sc("""These are the best cookie in the world for giving, honey. They travel well, they don't break, and they stay soft. Stack six in a tall glass jar, or wrap them in wax paper and tie them with red string, the way Grandma Pearl did. Put them in the mailbox for the mail carrier. Take a plate to the nurses at the hospital. They cost about eight cents a cookie.""",
   "stack of cookies in jar with red string", "EIGHT CENTS A COOKIE")
sc("""Every Christmas, I bring a tin to the fire station down the street. The young men there call me the cookie lady. Last year, one of them told me his grandmother used to make molasses cookies exactly like these, and he hadn't had one since she died. He ate four standing right there, and then he went outside for a while. I understood, sweetheart.""",
   "firefighters at station with cookie tin", "THE COOKIE LADY")

ch("Grandma's kitchen")
sc("""So one more time. Mild molasses, never blackstrap. Fresh spices. Chill the dough at least an hour, or overnight. Roll them in sugar. Take them out when the middles still look underdone. And a slice of bread in the tin. That's Grandma Pearl's molasses cookie, soft for two weeks, and the smell of Christmas in every bite.""",
   "plate of molasses cookies Christmas", "SOFT FOR TWO WEEKS")
sc("""Tell me in the comments, sweetheart. Did your grandmother make molasses cookies? And did she let you have two, or three? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas kitchen evening cookie tin", "TWO OR THREE?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma88", "Molasses Cookies EVERYONE's Grandma Made (Why Yours Go HARD)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Molasses was the common, cheap sweetener in American kitchens through the 19th century; blackstrap is the final, most bitter boiling.",
      "Recipe as written by Grandma Ruth: 3/4 cup butter, 1 cup brown sugar, 1 egg, 1/4 cup mild molasses, 2 1/4 cups flour, 2 tsp baking soda, 1/4 tsp salt, 2 tsp ginger, 1 tsp cinnamon, 1/2 tsp cloves; chilled, rolled in sugar, 350F for 9-10 minutes."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
